INSERT INTO translations (locale, translation_json) VALUES ('en', '{"hero":{"greeting":"Hi, I''m Shan Lin","title":"AI/Fullstack Developer","subtitle":"Building scalable AI and web applications with modern technologies","cta":"View My Work","contactMe":"Contact Me"},"navigation":{"home":"Home","about":"About","projects":"Projects","experience":"Experience","contact":"Contact"},"about":{"title":"About Me","subtitle":"aboutMe","paragraphs":{"para1":"I''m a full-stack engineer focused on AI-native products and high-performance backends. Recent representative projects include an AI-native TRPG platform, Rust/Python microservices API, 3D reconstruction application, ROS2 autonomous vehicle system, as well as engineering practice in control theory and computer vision.","para2":"In terms of tech stack, I use Next.js, TypeScript, Tailwind CSS and shadcn-UI for frontend/full-stack; build microservices with Rust (tokio/Axum) and Python FastAPI, combined with PostgreSQL, Redis, Docker and Github Action for CI/CD; practice LangChain/LangGraph, YOLOv5, OpenCV, Meta SAM2, Colmap and OpenMVS in AI and computer vision; and use ROS2, VINS-Fusion and Navigation2 with LQR and Luenberger methods in robotics and control.","para3":"I strive to combine solid engineering practices with excellent user experience: continuously refining AI-native products, building scalable microservices and data infrastructure, exploring automated 3D generation and autonomous systems, and constantly improving performance and maintainability."},"skillsTitle":"Technologies I Work With","skillCategories":[{"name":"language","skills":["Python","Rust","TypeScript","C++"]},{"name":"web","skills":["Next.js","Tailwind CSS","tokio/Axum","FastAPI"]},{"name":"infra","skills":["PostgreSQL","Redis","Docker","CI/CD"]},{"name":"ai","skills":["LangChain/LangGraph","DL/ML","Computer Vision","OpenCV","Data Analysis"]},{"name":"robotics","skills":["ROS2","System Modeling","Real-time Processing"]}],"stats":{"experience":{"value":"5+","label":"Years Experience"},"projects":{"value":"6+","label":"Projects Completed"}}},"projects":{"title":"My Projects","subtitle":"featuredProjects","featured":"Featured Projects","all":"All Projects","viewDetails":"View Details","technologies":"Technologies","duration":"Duration","team":"Team Size","role":"Role","status":"Status","overview":"Overview","features":"Features","challenges":"Challenges","outcomes":"Outcomes","live":"Live Demo","github":"GitHub"},"resume":{"title":"Resume","downloadPDF":"Download as PDF","downloading":"Generating PDF...","personalInfo":"Personal Information","contact":"Contact Information","skills":"Skills","tools":"Tools & Technologies","workExperience":"Work Experience","education":"Education","present":"Present"},"contact":{"title":"Let''s Work Together","subtitle":"letsWorkTogether","description":"I''m always interested in new opportunities and exciting projects. Whether you have a question or just want to say hi, I''ll try my best to get back to you!","getInTouch":"Get In Touch","contactInfo":{"email":{"label":"Email","value":"noreply@example.com"},"phone":{"label":"Phone","value":"+86 13798093084"},"location":{"label":"Location","value":"REDACTED"},"github":{"label":"GitHub","value":"github.com/Preference-cmd"}},"availableFor":{"title":"Available For","services":["AI/ML Integration","Full-stack Development","Computer Vision","Technical Consulting"]},"form":{"title":"Send Message","fields":{"name":{"label":"Name","placeholder":""},"email":{"label":"Email","placeholder":"john@example.com"},"subject":{"label":"Subject","placeholder":"Project Inquiry"},"message":{"label":"Message","placeholder":"Tell me about your project..."}},"submitButton":"Send Message","submitting":"Sending...","success":"Message sent successfully!","error":"Failed to send message. Please try again."},"footer":{"description":"AI/Fullstack Developer building scalable applications","copyright":"All rights reserved.","social":"Connect with me"}}');

